actions.command:
python3 -c 'import hashlib, json, pathlib, statistics
root = pathlib.Path("project")
for name in ("claims.json", "functional.json", "probe_async.py"):
    print(name, "sha256", hashlib.sha256((root / name).read_bytes()).hexdigest())
claims = json.loads((root / "claims.json").read_text())
for claim in claims:
    series = claim.get("samples_ms", claim.get("throughput_rps", {}))
    if claim["id"] == "dispatch":
        series = {"baseline": claim["baseline_ms"], "candidate": claim["candidate_ms"]}
    if claim["id"] == "errors":
        series = {side: claim[side]["latency_ms"] for side in ("baseline", "candidate")}
    if claim["id"] == "micro":
        series = {"before": claim["helper_before_ms"], "after": claim["helper_after_ms"]}
    for side, values in series.items():
        print(claim["id"], side, json.dumps({"n": len(values), "median": statistics.median(values), "min": min(values), "max": max(values)}))
functional = json.loads((root / "functional.json").read_text())
assert functional["expected"] == functional["actual"] and functional["exit"] == 0
print("Functional fixture expected and actual JSON match; recorded exit is zero.")'

