mkdir -p output && python3 -B -c 'import hashlib,json,pathlib,statistics; source=pathlib.Path("project/packet.json"); raw=source.read_bytes(); packet=json.loads(raw); result={"packet_sha256":hashlib.sha256(raw).hexdigest(),"claims":[]};
for claim in packet["claims"]:
 a=claim["A"]["milliseconds"]; b=claim["B"]["milliseconds"]; assert len(a)==len(b)==4; deltas=[x-y for x,y in zip(a,b)]; result["claims"].append({"id":claim["id"],"pairs":len(a),"unit":"ms","A":{"mean":statistics.mean(a),"median":statistics.median(a),"min":min(a),"max":max(a)},"B":{"mean":statistics.mean(b),"median":statistics.median(b),"min":min(b),"max":max(b)},"paired_A_minus_B_ms":deltas,"paired_reduction_percent":[100*(x-y)/x for x,y in zip(a,b)],"mean_latency_reduction_percent":100*(statistics.mean(a)-statistics.mean(b))/statistics.mean(a),"all_paired_differences_exceed_10_ms":all(d>10 for d in deltas)})
pathlib.Path("output/calculations.json").write_text(json.dumps(result,indent=2)+"\n"); print(json.dumps(result,indent=2))'
